        <div class="panel" id="member-details" hidden>
          <h3>Member and plan details on file</h3>
          <dl class="details">
            <div><dt>Member name</dt><dd id="md-name">—</dd></div>
            <div><dt>Date of birth</dt><dd id="md-dob">—</dd></div>
            <div><dt>Plan sponsor</dt><dd id="md-sponsor">—</dd></div>
            <div><dt>Division</dt><dd id="md-division">—</dd></div>
            <div><dt>Occupation</dt><dd id="md-occupation">—</dd></div>
            <div><dt>Coverage</dt><dd id="md-coverage">—</dd></div>
            <div><dt>Hire date</dt><dd id="md-hire">—</dd></div>
            <div><dt>Annual earnings</dt><dd id="md-earnings">—</dd></div>
          </dl>
        </div>
      </div>
